<?php
require __DIR__.'/auth.php';
requireLogin();
$user = currentUser();
$report = $_GET['report'] ?? '';
$year = (int)($_GET['year'] ?? date('Y'));
$month = (int)($_GET['month'] ?? date('n'));
$start = $end = '';
function rd($v){$t=strtotime($v);return $t?date('d-m-Y',$t):$v;}
function vd($v){$d=DateTime::createFromFormat('Y-m-d',$v);return $d&&$d->format('Y-m-d')===$v;}
if($report==='monthly'&&$year>=2000&&$year<=2100&&$month>=1&&$month<=12){$start=sprintf('%04d-%02d-01',$year,$month);$end=date('Y-m-t',strtotime($start));}
elseif($report==='six_months'){$end=date('Y-m-d');$start=date('Y-m-d',strtotime('-5 months',strtotime(date('Y-m-01'))));}
elseif($report==='yearly'&&$year>=2000&&$year<=2100){$start="$year-01-01";$end="$year-12-31";}
elseif($report==='custom'){$start=$_GET['start']??'';$end=$_GET['end']??'';if(!vd($start)||!vd($end)||$start>$end)$start=$end='';}
$rows=[];
if($start&&$end){$q=$db->prepare('SELECT lunch_date,meal_type,meal_time,food_item,quantity,notes FROM lunches WHERE user_id=? AND lunch_date BETWEEN ? AND ? ORDER BY lunch_date,meal_time,id');$q->execute([$_SESSION['user_id'],$start,$end]);$rows=$q->fetchAll();}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Food Reports</title><style>*{box-sizing:border-box}body{margin:0;background:#f4f7fb;font-family:system-ui,sans-serif;color:#172033}.wrap{width:min(100% - 20px,1100px);margin:auto;padding:18px 0}.top{display:flex;justify-content:space-between;margin-bottom:15px}.top a{color:#1d4ed8;text-decoration:none;font-weight:800}.hero,.card{border-radius:20px}.hero{background:linear-gradient(135deg,#0f172a,#1d4ed8);color:white;padding:22px;margin-bottom:15px}.hero h1{margin:0}.hero p{margin:5px 0;color:#dbeafe}.card{background:#fff;border:1px solid #e2e8f0;padding:19px;margin-bottom:15px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:15px}.filters{display:grid;grid-template-columns:1fr 1fr;gap:12px}label{display:block;font-size:12px;font-weight:800;margin:10px 0 6px}input,select,button{width:100%;padding:12px;border:1px solid #d7dce5;border-radius:11px;font:inherit}button{background:#0f172a;color:#fff;border:0;font-weight:800;margin-top:14px}.pill{display:inline-block;background:#eff6ff;color:#1d4ed8;padding:8px 11px;border-radius:99px;font-size:12px;font-weight:800;margin:3px}.download{margin-top:14px;display:flex;gap:8px}.download a{background:#0f172a;color:#fff;padding:11px 14px;border-radius:10px;text-decoration:none;font-size:12px;font-weight:800}.table{overflow:auto}table{width:100%;min-width:700px;border-collapse:collapse}th,td{padding:10px;border-bottom:1px solid #e2e8f0;text-align:left;font-size:12px}th{background:#f8fafc;color:#64748b}.empty{text-align:center;color:#64748b;padding:25px}@media(max-width:700px){.grid,.filters{grid-template-columns:1fr}}</style></head><body><main class="wrap"><div class="top"><a href="index.php">← Dashboard</a><a href="profile.php">👤 Profile</a></div><header class="hero"><h1>📊 Food Reports</h1><p><?=h($user['name'])?> · Personal food history</p></header><section class="grid"><div class="card"><h2>Report Filters</h2><form method="get" id="form"><div class="filters"><div><label>Report Type</label><select name="report" id="type" required><option value="">Select</option><option value="monthly" <?=$report==='monthly'?'selected':''?>>Monthly</option><option value="six_months" <?=$report==='six_months'?'selected':''?>>Last 6 Months</option><option value="yearly" <?=$report==='yearly'?'selected':''?>>Yearly</option><option value="custom" <?=$report==='custom'?'selected':''?>>Custom Range</option></select></div><div id="yearbox"><label>Year</label><input type="number" name="year" min="2000" max="2100" value="<?=h((string)$year)?>"></div></div><div id="monthbox"><label>Month</label><select name="month"><?php for($m=1;$m<=12;$m++):?><option value="<?=$m?>" <?=$month===$m?'selected':''?>><?=date('F',mktime(0,0,0,$m,1))?></option><?php endfor;?></select></div><div id="custombox"><label>Start Date (DD-MM-YYYY)</label><input id="sd" placeholder="01-09-2026" value="<?=$start?h(rd($start)):''?>"><input type="hidden" name="start" id="s" value="<?=h($start)?>"><label>End Date (DD-MM-YYYY)</label><input id="ed" placeholder="11-09-2026" value="<?=$end?h(rd($end)):''?>"><input type="hidden" name="end" id="e" value="<?=h($end)?>"></div><button>Generate Report</button></form></div><div class="card"><h2>Summary</h2><?php if($start&&$end):?><span class="pill">Entries: <?=count($rows)?></span><span class="pill">Days: <?=count(array_unique(array_column($rows,'lunch_date')))?></span><p><?=h(rd($start))?> → <?=h(rd($end))?></p><?php $c=[];foreach($rows as $r)$c[$r['meal_type']??'Lunch']=($c[$r['meal_type']??'Lunch']??0)+1;foreach($c as $n=>$v):?><span class="pill"><?=h($n)?>: <?=$v?></span><?php endforeach;?><div class="download"><a href="export.php?format=xlsx&start=<?=urlencode($start)?>&end=<?=urlencode($end)?>">⬇ Excel</a><a href="export.php?format=csv&start=<?=urlencode($start)?>&end=<?=urlencode($end)?>">⬇ CSV</a></div><?php else:?><div class="empty">Select a report to view your history.</div><?php endif;?></div></section><?php if($start&&$end):?><section class="card"><h2>Report Preview</h2><?php if(!$rows):?><div class="empty">No entries found.</div><?php else:?><div class="table"><table><tr><th>Date</th><th>Meal</th><th>Food</th><th>Quantity</th><th>Time</th><th>Notes</th></tr><?php foreach($rows as $r):?><tr><td><?=h(rd($r['lunch_date']))?></td><td><?=h($r['meal_type']??'Lunch')?></td><td><?=h($r['food_item'])?></td><td><?=h($r['quantity']??'')?></td><td><?=h($r['meal_time']??'')?></td><td><?=h($r['notes']??'')?></td></tr><?php endforeach;?></table></div><?php endif;?></section><?php endif;?><script>const t=document.getElementById('type'),y=document.getElementById('yearbox'),m=document.getElementById('monthbox'),c=document.getElementById('custombox');function toggle(){y.style.display=(t.value==='monthly'||t.value==='yearly')?'block':'none';m.style.display=t.value==='monthly'?'block':'none';c.style.display=t.value==='custom'?'block':'none'}t.onchange=toggle;toggle();function iso(v){const x=v.match(/^(\d{2})-(\d{2})-(\d{4})$/);if(!x)return null;const d=new Date(Date.UTC(+x[3],+x[2]-1,+x[1]));return d.getUTCFullYear()==+x[3]&&d.getUTCMonth()==+x[2]-1&&d.getUTCDate()==+x[1]?x[3]+'-'+x[2]+'-'+x[1]:null}document.getElementById('form').onsubmit=e=>{if(t.value==='custom'){const a=iso(document.getElementById('sd').value.trim()),b=iso(document.getElementById('ed').value.trim());if(!a||!b||a>b){e.preventDefault();alert('Enter valid DD-MM-YYYY dates.');return}document.getElementById('s').value=a;document.getElementById('e').value=b}};</script></main></body></html>